// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount, address user) public {
        vm.assume(user != address(0) && user != address(c));
        amount = bound(amount, 1, 100 ether);

        vm.deal(user, amount);
        vm.prank(user);
        c.addToBalance{value: amount}();

        uint256 userBalAfterDeposit = c.getBalance(user);
        uint256 contractBalAfterDeposit = address(c).balance;

        vm.prank(user);
        c.withdrawBalance();

        uint256 userBalAfterWithdraw = c.getBalance(user);
        uint256 contractBalAfterWithdraw = address(c).balance;

        assertEq(contractBalAfterWithdraw, userBalAfterWithdraw);
    }
}
